select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'body',md5(p.prosrc),'config',p.proconfig,'definer',p.prosecdef,'acl',p.proacl::text) order by n.nspname,p.proname) fingerprint from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('report_work_boundary','report_rows','report_query','dashboard_query','report_charts');
